insert into public.blog_posts (title, slug, excerpt, content, status, published_at)
values
('Why Python Remains Useful', 'why-python-remains-useful', 'Python is useful not because it is the fastest language, but because it makes many kinds of work approachable.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python lowers the distance between an idea and a working tool. Its readable syntax helps teams communicate intent, while a broad ecosystem makes it practical for automation, data analysis, web services, and machine learning."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Optimize for the whole task"}]},{"type":"paragraph","content":[{"type":"text","text":"Raw execution speed is only one part of engineering cost. Development time, maintenance, and library availability often matter more. When performance becomes a constraint, profile first and optimize only measured hot paths."}]}]}', 'published', now()),
('A Practical Guide to Idempotency', 'a-practical-guide-to-idempotency', 'Idempotency makes retries safe by ensuring repeated requests do not duplicate side effects.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An operation is idempotent when repeating it has the same effect as doing it once. This matters when a client times out: the server may have completed its work even though the response never arrived."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Use a stable request key"}]},{"type":"paragraph","content":[{"type":"text","text":"For side-effecting operations, accept an idempotency key scoped to the account and operation. Store it with the result in the same transaction. If the key returns, send back the existing result rather than repeating the work."}]}]}', 'published', now()),
('Transactions: Keep Related Changes Together', 'transactions-all-or-nothing', 'Transactions protect invariants when one logical operation updates several rows.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A transaction groups database changes so they either all commit or none do. This matters whenever partial success would violate a business rule, such as decrementing inventory without recording an order."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Keep transactions short"}]},{"type":"paragraph","content":[{"type":"text","text":"Use database constraints and short transactions to keep related state consistent. Do not wait for email, a payment provider, or another network service inside a transaction. Commit durable state first, then handle external side effects through a retryable job or outbox."}]}]}', 'published', now())
